using DomainModel.Context; using Microsoft.EntityFrameworkCore; namespace DataAccess.Repositories.Payment; public class PaymentRepository(ApplicationDbContext c):IPaymentRepository { public IQueryable<DomainModel.Models.Payment> Query(bool tracking=false)=>tracking?c.Payments:c.Payments.AsNoTracking(); public Task AddAsync(DomainModel.Models.Payment p)=>c.Payments.AddAsync(p).AsTask(); public Task<int> SaveChangesAsync()=>c.SaveChangesAsync(); }
